{
  "headline": "FDA's records trace our supply to a plant classified OAI 313 days before the posting",
  "headline_cites": ["D33"],
  "sentences": [
    {
      "text": "FDA first posted the sodium acetate shortage on 2015-02-17 and it remains current as of 2026-10-21.",
      "cites": ["E437", "D82"]
    },
    {
      "text": "The shortage is listed for Fresenius Kabi USA, LLC with an estimated next release in November 2026.",
      "cites": ["E437"]
    },
    {
      "text": "An import alert 66-40 was published on 2014-04-10, 313 days before the shortage posting.",
      "cites": ["D33"]
    },
    {
      "text": "Fresenius Kabi's U.S. plant (FEI 3001833549) received an OAI classification after an inspection ending 2013-01-11, 767 days before the posting.",
      "cites": ["D17", "E293"]
    },
    {
      "text": "A Warning Letter was issued to that plant on 2012-02-22, 1091 days before the posting.",
      "cites": ["D4", "E300"]
    },
    {
      "text": "Another Fresenius Kabi plant (FEI 3006028606) received an OAI classification after an inspection ending 2016-01-19, 336 days after the posting.",
      "cites": ["D53", "E275"]
    },
    {
      "text": "The rule-selected alternate manufacturer is Ionis Pharmaceuticals, Inc., which is not on FDA's shortage list today.",
      "cites": ["D79"]
    }
  ]
}
